#include <algorithm>
#include <climits>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

using namespace std;

const int N = 1000100;

vector<pair<long long, long long>> points;
bool isUsed[N];

__int128 ccw(const pair<long long, long long>& a,
             const pair<long long, long long>& b,
             const pair<long long, long long>& c) {
    return static_cast<__int128>(b.first - a.first) * (c.second - a.second) -
           static_cast<__int128>(b.second - a.second) * (c.first - a.first);
}

void solve() {
    int n;
    cin >> n;

    points.reserve(n);
    for (int i = 0; i < n; ++i) {
        long long x, y;
        cin >> x >> y;
        points.push_back({x, y});
    }

    string s;
    cin >> s;

    pair<long long, long long> curP = {LLONG_MAX, LLONG_MAX};
    int pivot = 0;

    for (int i = 0; i < n; ++i) {
        if (points[i].second < curP.second ||
            (points[i].second == curP.second &&
             points[i].first < curP.first)) {
            curP = points[i];
            pivot = i;
        }
    }

    isUsed[pivot] = true;

    for (char turn : s) {
        cout << pivot + 1 << ' ';

        int middle = -1;
        for (int j = 0; j < n; ++j) {
            if (isUsed[j]) {
                continue;
            }

            if (middle == -1 ||
                (turn == 'L' &&
                 ccw(points[pivot], points[middle], points[j]) < 0) ||
                (turn != 'L' &&
                 ccw(points[pivot], points[middle], points[j]) > 0)) {
                middle = j;
            }
        }

        pivot = middle;
        isUsed[pivot] = true;
    }

    cout << pivot + 1 << ' ';
    for (int i = 0; i < n; ++i) {
        if (!isUsed[i]) {
            cout << i + 1 << '\n';
        }
    }
}

int main() {
    solve();
    return 0;
}

